// Auto-submode: pick any user Executa.
const sess = await anna.agent.session.create({
  submode: "auto",
  label: "daily-summary",
  quotaCaps: { max_tokens_per_call: 2000 },
});
// → { app_session_uuid: "aps_…", expires_in: 3600, submode: "auto",
//     fixed_client_id: null, granted_tools: ["executa-fetch:*", …] }

// Fixed-submode: pin to one Executa.
const pinned = await anna.agent.session.create({
  submode: "fixed",
  fixed_client_id: "executa-write-notes-abc123",
});

const cat = await anna.agent.session.catalog();
const usable = cat.platform_tools.filter(t => t.eligible).map(t => t.name);
// e.g. ["fs_read_file", "web_search"] — legal values for quotaCaps.allowed_tools
const sess = await anna.agent.session({
  submode: "auto",
  quotaCaps: { inherit_host_tools: false, allowed_tools: ["fs_read_file"] },
});
// lean read-only sandbox session — the agent can read files but has no
// fs_write_file / exec_run, and hundreds of inherited host tools (≈100K
// prompt tokens) are avoided

// Higher-level (preferred): the SDK helper wraps the stream into an AsyncIterable.
const sess = await anna.agent.session({ submode: "auto" });
const stream = sess.run({ content: "Summarise my open tabs.", recursion_limit: 12 });

for await (const frame of stream) {
  if (frame.event === "error") { renderError(frame.message); break; }
  if (frame.event === "end") { finalise(frame.run_id); break; }
  if (frame.event === "run_meta" && frame.warnings?.length) warn(frame.warnings);
  const delta = frame.choices?.[0]?.delta;
  if (!delta) continue;                       // queued/started/keepalive
  if (delta.content) appendToken(delta.content);
  if (delta.tool_start) log(`→ ${delta.tool_start.name}`);
  if (delta.tool_end) log(`← ${delta.tool_end.name}`);
  if (delta.task_complete) usage = delta.task_complete.token_usage;
  if (frame.error) renderError(`${frame.error_type}: ${frame.error}`);
}

// Lower-level (manual stream routing):
const { stream_id, run_id } = await anna.agent.session.run({
  app_session_uuid: "aps_…",
  content: "hi",
  run_id: crypto.randomUUID(),
});
anna.on("rpc.stream", (frame) => {
  if (frame.stream_id !== stream_id) return;
  // …reassemble by frame.seq, watch for frame.done
});

const stream = sess.run({ content: "long task" });
// Cancel after 30 s if still running.
setTimeout(() => sess.cancel(stream.runId), 30_000);
for await (const frame of stream) {
  if (frame.event === "end") break;
}

const { messages } = await anna.agent.session.history({
  app_session_uuid: sess.app_session_uuid,
  limit: 20,
});
for (const m of messages) renderBubble(m.role, m.content);

// Tear down on unmount.
window.addEventListener("pagehide", () => {
  sess.delete().catch(() => { /* best-effort */ });
});

// Or via the SDK helper:
await sess.delete();

// Re-attach after an iframe reload instead of minting a duplicate session.
const { sessions } = await anna.agent.session.list({ limit: 10 });
const latest = sessions[0];
if (latest) {
  await anna.agent.session.refresh({ app_session_uuid: latest.app_session_uuid });
  // …now safe to run() against latest.app_session_uuid
} else {
  await anna.agent.session.create({ submode: "auto" });
}

// Proactive refresh ~1 min before the idle deadline.
const meta = await anna.agent.session.refresh({ app_session_uuid: sess.app_session_uuid });
const msUntilExpiry = meta.session_expires_in * 1000;
setTimeout(() => anna.agent.session.refresh({ app_session_uuid: sess.app_session_uuid }), msUntilExpiry - 60_000);
